import test from 'node:test';import assert from 'node:assert/strict';import {eiQuality,qualityByBlueprint} from '../../reda-2/ei-quality-model.mjs';
test('quality metrics separate decisions, overrides and post-change cases',()=>{const d=[{id:'1',action:'advance',applied:true,result_plan_id:'p2',created_at:'2026-09-01'},{id:'2',action:'hold',applied:false,created_at:'2026-09-02'}],r=[{decision_id:'1',verdict:'override'}],c=[{plan_id:'p2',created_at:'2026-09-03'}];const q=eiQuality(d,r,c);assert.deepEqual([q.advance,q.hold,q.overridden,q.postChangeCases],[1,1,1,1]);assert.equal(q.overrideRate,100)});
test('blueprint grouping does not rank clinical quality',()=>{const x=qualityByBlueprint([{action:'review',blueprint_id:'knee'},{action:'advance',blueprint_id:'knee'},{action:'hold',blueprint_id:'shoulder'}]);assert.equal(x.find(v=>v.blueprint==='knee').escalate,1);assert.ok(!('score' in x[0]))});
